import { Impit } from 'impit';

// Verified against ZipRecruiter on 2026-10-21. Firefox profiles are the most
// consistent; chrome125 is kept as a last-resort profile when Firefox is
// challenged. Do not add profiles here without live evidence.
export const VERIFIED_PROFILES = ['firefox', 'firefox128', 'firefox133', 'chrome125'];

// The navigation accept value is required by the target. Without it Cloudflare
// answers HTTP 403 even when the TLS fingerprint itself is accepted. The rest
// of the fingerprint (user-agent, sec-ch-ua, sec-fetch-*) is generated by impit
// from the selected profile and must not be overridden.
export const NAVIGATION_HEADERS = {
    accept: 'text/html,application/xhtml+xml,application/xml;q=0.9,*/*;q=0.8',
    'accept-language': 'en-US,en;q=0.9',
};

const DEFAULT_TIMEOUT_MS = 45000;

function parseRetryAfter(headers) {
    const raw = headers?.get?.('retry-after');
    if (!raw) return null;
    const seconds = Number(raw);
    if (Number.isFinite(seconds)) return Math.max(seconds, 0) * 1000;
    const timestamp = Date.parse(raw);
    return Number.isNaN(timestamp) ? null : Math.max(timestamp - Date.now(), 0);
}

export function createHttpTransport({ proxyConfiguration, proxyInput = {}, log, timeoutMs = DEFAULT_TIMEOUT_MS } = {}) {
    const groups = (proxyInput?.groups || proxyInput?.apifyProxyGroups || []).map((group) =>
        String(group).toUpperCase(),
    );
    const usesUnblocker = groups.includes('UNBLOCKER');
    const clients = new Map();
    let order = [...VERIFIED_PROFILES];
    let proxyUrl;
    let proxyRotations = 0;
    let initialized = false;

    async function createProxyUrl() {
        if (!proxyConfiguration) return undefined;
        const sessionId = usesUnblocker ? undefined : `ziprecruiter_${Date.now()}_${proxyRotations}`;
        return proxyConfiguration.newUrl(sessionId);
    }

    async function init() {
        if (initialized) return;
        proxyUrl = await createProxyUrl();
        initialized = true;
    }

    function clientFor(profile) {
        const key = `${profile}|${proxyUrl || 'direct'}`;
        let client = clients.get(key);
        if (!client) {
            client = new Impit({
                browser: profile,
                timeout: timeoutMs,
                ...(proxyUrl ? { proxyUrl } : {}),
            });
            clients.set(key, client);
        }
        return client;
    }

    return {
        init,
        get profiles() {
            return [...order];
        },
        get hasProxy() {
            return Boolean(proxyUrl);
        },
        get proxyRotations() {
            return proxyRotations;
        },
        async fetchOnce(url, profile) {
            await init();
            const response = await clientFor(profile).fetch(url, { headers: NAVIGATION_HEADERS });
            const html = await response.text();
            return {
                html,
                status: response.status,
                profile,
                usingProxy: Boolean(proxyUrl),
                retryAfterMs: parseRetryAfter(response.headers),
            };
        },
        markSuccess(profile) {
            order = [profile, ...order.filter((candidate) => candidate !== profile)];
        },
        markFailure(profile) {
            order = [...order.filter((candidate) => candidate !== profile), profile];
        },
        async rotateProxy() {
            if (!proxyConfiguration) return false;
            proxyRotations += 1;
            proxyUrl = await createProxyUrl();
            log?.debug(`Rotated proxy session (rotation ${proxyRotations}).`);
            return true;
        },
        dispose() {
            clients.clear();
        },
    };
}
